import { SharedArray } from 'k6/data';
import { sleep, check } from 'k6';
import { Counter, Trend } from 'k6/metrics';

import { getQuiz, startQuiz, submitAnswer, finalizeQuiz, completeQuizFlow } from './queries/quiz.js';

// Load configuration from JSON file generated by tokengen
const config = JSON.parse(open('../config.json'));

// SharedArray ensures tokens are only loaded once and shared across VUs
const tokens = new SharedArray('tokens', function () {
    return config.tokens;
});

// Get base URL and quiz ID from config
const baseUrl = config.baseUrl;
const quizId = __ENV.QUIZ_ID || 'QZ01LOADTESTQUIZ000000000000';

// Custom metrics for quiz testing
const quizCompletions = new Counter('quiz_completions');
const quizSkipped = new Counter('quiz_skipped');
const quizFailures = new Counter('quiz_failures');
const quizScore = new Trend('quiz_score');
const quizDuration = new Trend('quiz_duration');

// Test configuration
export const options = {
    scenarios: {
        // Scenario 1: Quiz completion load test
        // Simulates users completing quizzes at a steady rate
        quiz_completion: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '10s', target: parseInt(__ENV.QUIZ_VUS) || 20 },
                { duration: __ENV.DURATION || '5m', target: parseInt(__ENV.QUIZ_VUS) || 20 },
                { duration: '10s', target: 0 },
            ],
            exec: 'quizCompletion',
        },
        // Scenario 2: Quiz spike test
        // Many users starting quizzes simultaneously
        quiz_spike: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '5s', target: parseInt(__ENV.SPIKE_VUS) || 100 },
                { duration: __ENV.SPIKE_HOLD || '1m', target: parseInt(__ENV.SPIKE_VUS) || 100 },
                { duration: '5s', target: 0 },
            ],
            exec: 'quizSpike',
            startTime: __ENV.SPIKE_START || '0s',
        },
        // Scenario 3: Quiz stress test
        // High constant rate of quiz completions
        quiz_stress: {
            executor: 'constant-arrival-rate',
            rate: parseInt(__ENV.QUIZ_RPS) || 10,
            timeUnit: '1s',
            duration: __ENV.STRESS_DURATION || '5m',
            preAllocatedVUs: parseInt(__ENV.QUIZ_RPS) || 10,
            maxVUs: 500,
            exec: 'quizStress',
            startTime: __ENV.STRESS_START || '0s',
        },
    },
    thresholds: {
        // HTTP thresholds
        http_req_duration: ['p(95)<1000', 'p(99)<2000'],
        http_req_failed: ['rate<0.05'],
        // Quiz-specific thresholds
        quiz_completions: ['count>0'],
        quiz_failures: ['rate<0.1'],
        quiz_score: ['avg>8'], // Average 8+ correct out of 10
    },
};

/**
 * Get a random token from the pool
 */
function getRandomToken() {
    const index = Math.floor(Math.random() * tokens.length);
    return tokens[index];
}

/**
 * Quiz completion scenario: Complete full quiz flow
 */
export function quizCompletion() {
    const { token } = getRandomToken();
    const startTime = Date.now();

    // Complete the full quiz flow
    const result = completeQuizFlow(baseUrl, token, quizId, true);

    const duration = Date.now() - startTime;
    quizDuration.add(duration);

    if (result.success) {
        if (result.skipped) {
            // User already completed - this is expected, not a failure
            quizSkipped.add(1);
        } else {
            quizCompletions.add(1);
            quizScore.add(result.score);

            check(result, {
                'quiz completed successfully': (r) => r.success,
                'points awarded': (r) => r.pointsAwarded > 0,
                'perfect score': (r) => r.score === r.maxScore,
            });
        }
    } else {
        quizFailures.add(1);
        console.error(`Quiz flow failed: ${result.error}`);
    }

    // Random think time between quiz completions
    sleep(Math.random() * 2 + 1);
}

/**
 * Quiz spike scenario: Same as completion but under spike load
 */
export function quizSpike() {
    quizCompletion();
}

/**
 * Quiz stress scenario: High-frequency quiz completions
 */
export function quizStress() {
    const { token } = getRandomToken();

    // Under stress, users might answer randomly (simulate realistic behavior)
    const correctAnswers = Math.random() > 0.3; // 70% try to answer correctly

    const startTime = Date.now();
    const result = completeQuizFlow(baseUrl, token, quizId, correctAnswers);
    const duration = Date.now() - startTime;

    quizDuration.add(duration);

    if (result.success) {
        if (result.skipped) {
            quizSkipped.add(1);
        } else {
            quizCompletions.add(1);
            quizScore.add(result.score);
        }
    } else {
        quizFailures.add(1);
    }
}

/**
 * Default function
 */
export default function () {
    quizCompletion();
}

/**
 * Setup function - runs once before the test starts
 */
export function setup() {
    console.log(`Quiz load test starting with ${tokens.length} user tokens`);
    console.log(`Target URL: ${baseUrl}`);
    console.log(`Quiz ID: ${quizId}`);

    // Verify quiz exists
    const { token } = tokens[0];
    const quiz = getQuiz(baseUrl, token, quizId);
    if (!quiz) {
        throw new Error(`Quiz ${quizId} not found or inaccessible`);
    }

    console.log(`Quiz found: ${quiz.name} with ${quiz.questions.length} questions`);
    console.log(`Completion points: ${quiz.completionPoints}`);

    return {
        tokenCount: tokens.length,
        quizName: quiz.name,
        questionCount: quiz.questions.length,
    };
}

/**
 * Teardown function - runs once after the test ends
 */
export function teardown(data) {
    console.log(`Quiz load test completed.`);
    console.log(`  Tokens used: ${data.tokenCount}`);
    console.log(`  Quiz: ${data.quizName}`);
    console.log(`  Questions: ${data.questionCount}`);
}
